# ==========================================
# 3. ส่งคำสั่งขยับแบบ Direct Control
# ==========================================
print('กำลังเริ่ม Simulation...')
# เปิด Stepping Mode เพื่อให้ลูป Python กับเวลาในซิมซิงค์กันเป๊ะๆ
sim.setStepping(True) 
sim.startSimulation()

# วนลูปส่งมุมข้อต่อทีละสเตป
for i in range(len(times)):
    # สั่งขยับทีละข้อต่อ
    sim.setJointPosition(j_handles[0], j1[i])
    sim.setJointPosition(j_handles[1], j2[i])
    sim.setJointPosition(j_handles[2], j3[i])
    sim.setJointPosition(j_handles[3], j4[i])
    sim.setJointPosition(j_handles[4], j5[i])
    sim.setJointPosition(j_handles[5], j6[i])
    
    # สั่งให้เวลาในโลกจำลองเดินหน้า 1 สเตป (dt = 0.05)
    sim.step() 

print('ขยับเสร็จสิ้น! กดปุ่ม Enter บนคีย์บอร์ดที่หน้าต่างนี้เพื่อหยุดซิมและดูกราฟ...')
input() # ใช้ input() รอรับคำสั่งแทน getch

sim.setStepping(False)
sim.stopSimulation()
print('Program ended')

# ==========================================
# 4. พล็อตกราฟ (เหมือนของเดิม)
# ==========================================
t = times
plt.figure() # plot joint angle

